import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { Project, Canvas, Folder, NodeCard } from '@/types'
import * as api from '@/services/api'

interface ProjectsState {
  projects: Project[]
  currentProject: Project | null
  currentProjectId: number | null  // 持久化项目ID
  canvases: Canvas[]
  folders: Folder[]
  nodePool: NodeCard[]
  isLoading: boolean
  error: string | null

  // Actions
  loadProjects: () => Promise<void>
  setCurrentProject: (project: Project | null) => Promise<void>
  restoreCurrentProject: () => Promise<void>  // 恢复上次的项目
  loadCanvases: (projectId: number) => Promise<void>
  loadFolders: (projectId: number) => Promise<void>
  loadNodePool: (projectId: number) => Promise<void>
  createProject: (data: Omit<Project, 'id' | 'createdAt' | 'updatedAt'>) => Promise<void>
  updateProject: (id: number, data: Partial<Project>) => Promise<void>
  deleteProject: (id: number) => Promise<void>

  // Canvas actions
  createCanvas: (projectId: number, data: Partial<Canvas>) => Promise<void>
  updateCanvas: (id: number, data: Partial<Canvas>) => Promise<void>
  deleteCanvas: (id: number) => Promise<void>

  // Folder actions
  createFolder: (projectId: number, data: Omit<Folder, 'id' | 'createdAt'>) => Promise<void>
  updateFolder: (id: number, data: Partial<Folder>) => Promise<void>
  deleteFolder: (id: number) => Promise<void>

  // Node pool actions
  addToNodePool: (projectId: number, data: Omit<NodeCard, 'id' | 'createdAt' | 'useCount'>) => Promise<void>
  removeFromNodePool: (id: number) => Promise<void>

  clearError: () => void
}

export const useProjectsStore = create<ProjectsState>()(
  persist(
    (set, get) => ({
      projects: [],
      currentProject: null,
      currentProjectId: null,  // 新增：持久化项目ID
      canvases: [],
      folders: [],
      nodePool: [],
      isLoading: false,
      error: null,

      loadProjects: async () => {
        set({ isLoading: true, error: null })
        try {
          const projects = await api.getProjects()
          set({ projects, isLoading: false })
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to load projects',
            isLoading: false,
          })
        }
      },

      setCurrentProject: async (project) => {
        set({
          currentProject: project,
          currentProjectId: project?.id || null  // 保存项目ID
        })
        if (project) {
          await Promise.all([
            get().loadCanvases(project.id),
            get().loadFolders(project.id),
            get().loadNodePool(project.id),
          ])
        }
      },

      // 新增：恢复上次的项目
      restoreCurrentProject: async () => {
        const { currentProjectId, projects } = get()
        if (currentProjectId && projects.length > 0) {
          const project = projects.find(p => p.id === currentProjectId)
          if (project) {
            await get().setCurrentProject(project)
          }
        }
      },

      loadCanvases: async (projectId) => {
        set({ isLoading: true, error: null })
        try {
          const canvases = await api.getCanvases(projectId)
          set({ canvases, isLoading: false })
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to load canvases',
            isLoading: false,
          })
        }
      },

      loadFolders: async (projectId) => {
        set({ isLoading: true, error: null })
        try {
          const folders = await api.getFolders(projectId)
          set({ folders, isLoading: false })
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to load folders',
            isLoading: false,
          })
        }
      },

      loadNodePool: async (projectId) => {
        set({ isLoading: true, error: null })
        try {
          const nodePool = await api.getNodePool(projectId)
          set({ nodePool, isLoading: false })
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to load node pool',
            isLoading: false,
          })
        }
      },

      createProject: async (data) => {
        set({ isLoading: true, error: null })
        try {
          const project = await api.createProject(data)
          set((state) => ({
            projects: [...state.projects, project],
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to create project',
            isLoading: false,
          })
          throw error
        }
      },

      updateProject: async (id, data) => {
        set({ isLoading: true, error: null })
        try {
          const updated = await api.updateProject(id, data)
          set((state) => ({
            projects: state.projects.map((p) => (p.id === id ? updated : p)),
            currentProject: state.currentProject?.id === id ? updated : state.currentProject,
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to update project',
            isLoading: false,
          })
          throw error
        }
      },

      deleteProject: async (id) => {
        set({ isLoading: true, error: null })
        try {
          await api.deleteProject(id)
          set((state) => ({
            projects: state.projects.filter((p) => p.id !== id),
            currentProject: state.currentProject?.id === id ? null : state.currentProject,
            currentProjectId: state.currentProjectId === id ? null : state.currentProjectId,
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to delete project',
            isLoading: false,
          })
          throw error
        }
      },

      createCanvas: async (projectId, data) => {
        set({ isLoading: true, error: null })
        try {
          const canvas = await api.createCanvas(projectId, data)
          set((state) => ({
            canvases: [...state.canvases, canvas],
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to create canvas',
            isLoading: false,
          })
          throw error
        }
      },

      updateCanvas: async (id, data) => {
        set({ isLoading: true, error: null })
        try {
          const updated = await api.updateCanvas(id, data)
          set((state) => ({
            canvases: state.canvases.map((c) => (c.id === id ? updated : c)),
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to update canvas',
            isLoading: false,
          })
          throw error
        }
      },

      deleteCanvas: async (id) => {
        set({ isLoading: true, error: null })
        try {
          await api.deleteCanvas(id)
          set((state) => ({
            canvases: state.canvases.filter((c) => c.id !== id),
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to delete canvas',
            isLoading: false,
          })
          throw error
        }
      },

      createFolder: async (projectId, data) => {
        set({ isLoading: true, error: null })
        try {
          const folder = await api.createFolder(projectId, data)
          set((state) => ({
            folders: [...state.folders, folder],
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to create folder',
            isLoading: false,
          })
          throw error
        }
      },

      updateFolder: async (id, data) => {
        set({ isLoading: true, error: null })
        try {
          const updated = await api.updateFolder(id, data)
          set((state) => ({
            folders: state.folders.map((f) => (f.id === id ? updated : f)),
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to update folder',
            isLoading: false,
          })
          throw error
        }
      },

      deleteFolder: async (id) => {
        set({ isLoading: true, error: null })
        try {
          await api.deleteFolder(id)
          set((state) => ({
            folders: state.folders.filter((f) => f.id !== id),
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to delete folder',
            isLoading: false,
          })
          throw error
        }
      },

      addToNodePool: async (projectId, data) => {
        set({ isLoading: true, error: null })
        try {
          const card = await api.addToNodePool(projectId, data)
          set((state) => ({
            nodePool: [...state.nodePool, card],
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to add to node pool',
            isLoading: false,
          })
          throw error
        }
      },

      removeFromNodePool: async (id) => {
        set({ isLoading: true, error: null })
        try {
          await api.removeFromNodePool(id)
          set((state) => ({
            nodePool: state.nodePool.filter((c) => c.id !== id),
            isLoading: false,
          }))
        } catch (error) {
          set({
            error: error instanceof Error ? error.message : 'Failed to remove from node pool',
            isLoading: false,
          })
          throw error
        }
      },

      clearError: () => set({ error: null }),
    }),
    {
      name: 'projects-storage',
      partialize: (state) => ({
        // 只持久化 currentProjectId，不持久化整个 currentProject 对象
        currentProjectId: state.currentProjectId,
      }),
    }
  )
)
