import { useState, useRef, useEffect, useCallback } from 'react'
import { useCanvasStore } from '@/store/useCanvasStore'
import { useUIStore } from '@/store/useUIStore'
import { NodeContextMenu } from './NodeContextMenu'
import { uploadFile } from '@/services/api'
import { snapToGrid } from '@/utils/canvas'
import { CANVAS_DEFAULTS } from '@/constants'
import type { Node } from '@/types'

interface NodeItemProps {
  node: Node
  isSelected: boolean
  zoom: number
  onDragStart?: (nodeId: string, e: React.MouseEvent) => void
  onDragEnd?: () => void
}

const RESIZE_HANDLE_SIZE = 16

type EditingField = 'title' | 'content' | null

export function NodeItem({ node, isSelected, zoom, onDragStart, onDragEnd }: NodeItemProps) {
  const {
    nodes,
    updateNode,
    setSelectedIds,
    addToSelection,
    removeFromSelection,
  } = useCanvasStore()

  const { setSelectedType, currentTool } = useUIStore()

  const [isDragging, setIsDragging] = useState(false)
  const [isResizing, setIsResizing] = useState(false)
  const [resizeDirection, setResizeDirection] = useState<string>('')
  const [isContextMenuOpen, setIsContextMenuOpen] = useState(false)
  const [contextMenuPosition, setContextMenuPosition] = useState({ x: 0, y: 0 })
  const [isComposing, setIsComposing] = useState(false)
  const [editingField, setEditingField] = useState<EditingField>(null)
  const [isHovered, setIsHovered] = useState(false)
  // 本地状态用于拖动时的实时更新，避免频繁更新全局状态
  const [localPosition, setLocalPosition] = useState({ x: node.x, y: node.y })
  const [localSize, setLocalSize] = useState({ width: node.width, height: node.height })

  const nodeRef = useRef<HTMLDivElement>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const titleRef = useRef<HTMLDivElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)
  const dragStartRef = useRef({ x: 0, y: 0, nodeX: node.x, nodeY: node.y })
  const resizeStartRef = useRef({ x: 0, y: 0, width: node.width, height: node.height })
  const justFinishedDragRef = useRef(false)
  const lastSyncedNodeRef = useRef<{ x: number; y: number; width: number; height: number } | null>(null)
  const editingTitleRef = useRef<string>('')
  const editingContentRef = useRef<string>('')
  const { addToast } = useUIStore()

  const isEditingTitle = editingField === 'title'
  const isEditingContent = editingField === 'content'

  useEffect(() => {
    if (!isDragging && !isResizing && !justFinishedDragRef.current) {
      const shouldSync = !lastSyncedNodeRef.current ||
        lastSyncedNodeRef.current.x !== node.x ||
        lastSyncedNodeRef.current.y !== node.y ||
        lastSyncedNodeRef.current.width !== node.width ||
        lastSyncedNodeRef.current.height !== node.height

      if (shouldSync) {
        setLocalPosition({ x: node.x, y: node.y })
        setLocalSize({ width: node.width, height: node.height })
        lastSyncedNodeRef.current = { x: node.x, y: node.y, width: node.width, height: node.height }
      }
    }
  }, [node.x, node.y, node.width, node.height, isDragging, isResizing, justFinishedDragRef.current])

  // 进入编辑模式时初始化内容
  useEffect(() => {
    if (editingField === 'title') {
      editingTitleRef.current = node.title || ''
      document.body.classList.add('allow-text-selection')
      setTimeout(() => {
        if (titleRef.current) {
          if (!titleRef.current.innerHTML) {
            titleRef.current.innerHTML = editingTitleRef.current
          }
          titleRef.current.focus()
          const range = document.createRange()
          const selection = window.getSelection()
          if (titleRef.current.childNodes.length > 0) {
            range.selectNodeContents(titleRef.current)
            range.collapse(false)
          } else {
            range.setStart(titleRef.current, 0)
            range.collapse(true)
          }
          selection?.removeAllRanges()
          selection?.addRange(range)
        }
      }, 0)
    } else if (editingField === 'content') {
      editingContentRef.current = node.content || ''
      document.body.classList.add('allow-text-selection')
      setTimeout(() => {
        if (contentRef.current) {
          if (!contentRef.current.innerHTML) {
            contentRef.current.innerHTML = editingContentRef.current
          }
          contentRef.current.focus()
          const range = document.createRange()
          const selection = window.getSelection()
          if (contentRef.current.childNodes.length > 0) {
            range.selectNodeContents(contentRef.current)
            range.collapse(false)
          } else {
            range.setStart(contentRef.current, 0)
            range.collapse(true)
          }
          selection?.removeAllRanges()
          selection?.addRange(range)
        }
      }, 0)
    } else {
      document.body.classList.remove('allow-text-selection')
    }

    return () => {
      document.body.classList.remove('allow-text-selection')
    }
  }, [editingField])

  // 保存标题
  const saveTitle = useCallback(() => {
    if (titleRef.current && isEditingTitle) {
      const title = titleRef.current.innerHTML
      if (title !== editingTitleRef.current) {
        updateNode(node.id, { title })
        editingTitleRef.current = title
      }
    }
  }, [isEditingTitle, node.id, updateNode])

  // 保存内容
  const saveContent = useCallback(() => {
    if (contentRef.current && isEditingContent) {
      const content = contentRef.current.innerHTML
      if (content !== editingContentRef.current) {
        updateNode(node.id, { content })
        editingContentRef.current = content
      }
    }
  }, [isEditingContent, node.id, updateNode])

  // Handle node selection
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      if (editingField !== null) return

      e.stopPropagation()

      const target = e.target as HTMLElement
      const resizeTarget = target.closest('[data-resize]') as HTMLElement
      if (resizeTarget) {
        const direction = resizeTarget.dataset.resize
        setResizeDirection(direction)
        setIsResizing(true)
        resizeStartRef.current = {
          x: e.clientX,
          y: e.clientY,
          width: node.width,
          height: node.height,
        }
        return
      }

      // Only allow selection and dragging in select tool
      if (currentTool !== 'select') {
        return
      }

      if (e.shiftKey) {
        if (isSelected) {
          removeFromSelection(node.id)
        } else {
          addToSelection(node.id)
        }
      } else {
        setSelectedIds([node.id])
        setSelectedType('node')
      }

      if (!node.locked) {
        setIsDragging(true)
        dragStartRef.current = {
          x: e.clientX,
          y: e.clientY,
          nodeX: node.x,
          nodeY: node.y,
        }
        onDragStart?.(node.id, e)
        // 触发自定义事件，通知 CanvasPage 开始拖动
        window.dispatchEvent(new CustomEvent('nodeDragStart', {
          detail: { nodeId: node.id, x: node.x, y: node.y }
        }))
      }
    },
    [
      editingField,
      isSelected,
      node.locked,
      node.x,
      node.y,
      node.width,
      node.height,
      setSelectedIds,
      addToSelection,
      removeFromSelection,
      onDragStart,
      node.id,
      currentTool,
    ]
  )

  // Handle mouse move for dragging and resizing
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isDragging && !node.locked) {
        e.preventDefault()
        const dx = (e.clientX - dragStartRef.current.x) / zoom
        const dy = (e.clientY - dragStartRef.current.y) / zoom
        let newPos = {
          x: dragStartRef.current.nodeX + dx,
          y: dragStartRef.current.nodeY + dy,
        }
        
        const { dragMode: currentDragMode } = useUIStore.getState()
        
        if (currentDragMode === 'grid') {
          const snappedPos = {
            x: snapToGrid(newPos.x, CANVAS_DEFAULTS.GRID_SIZE),
            y: snapToGrid(newPos.y, CANVAS_DEFAULTS.GRID_SIZE),
          }
          newPos = snappedPos
        }
        
        setLocalPosition(newPos)
        window.dispatchEvent(new CustomEvent('nodeDragMove', {
          detail: { nodeId: node.id, x: newPos.x, y: newPos.y }
        }))
      }

      if (isResizing) {
        e.preventDefault()
        const dx = (e.clientX - resizeStartRef.current.x) / zoom
        const dy = (e.clientY - resizeStartRef.current.y) / zoom

        let newWidth = resizeStartRef.current.width
        let newHeight = resizeStartRef.current.height
        let newX = localPosition.x
        let newY = localPosition.y

        if (resizeDirection.includes('e')) {
          newWidth = Math.max(100, resizeStartRef.current.width + dx)
        }
        if (resizeDirection.includes('w')) {
          newWidth = Math.max(100, resizeStartRef.current.width - dx)
          newX = dragStartRef.current.nodeX + dx
        }
        if (resizeDirection.includes('s')) {
          newHeight = Math.max(60, resizeStartRef.current.height + dy)
        }
        if (resizeDirection.includes('n')) {
          newHeight = Math.max(60, resizeStartRef.current.height - dy)
          newY = dragStartRef.current.nodeY + dy
        }

        // 只更新本地状态
        setLocalPosition({ x: newX, y: newY })
        setLocalSize({ width: newWidth, height: newHeight })
      }
    }

    const handleMouseUp = () => {
      if (isDragging || isResizing) {
        // 拖动/调整大小时才更新全局状态
        if (isDragging) {
          updateNode(node.id, {
            x: localPosition.x,
            y: localPosition.y,
          })
          // 设置标志，防止 useEffect 立即重置位置
          justFinishedDragRef.current = true
          // 更新 lastSyncedNodeRef 为新位置，防止被覆盖
          lastSyncedNodeRef.current = { x: localPosition.x, y: localPosition.y, width: localSize.width, height: localSize.height }
          // 延迟清除标志，允许 React 状态更新完成
          setTimeout(() => {
            justFinishedDragRef.current = false
          }, 200)
          // 触发自定义事件，通知 CanvasPage 结束拖动
          window.dispatchEvent(new CustomEvent('nodeDragEnd', {
            detail: { nodeId: node.id }
          }))
        }
        if (isResizing) {
          updateNode(node.id, {
            x: localPosition.x,
            y: localPosition.y,
            width: localSize.width,
            height: localSize.height,
          })
          justFinishedDragRef.current = true
          setTimeout(() => {
            justFinishedDragRef.current = false
          }, 100)
        }
        setIsDragging(false)
        setIsResizing(false)
        setResizeDirection('')
        onDragEnd?.()
      }
    }

    if (isDragging || isResizing) {
      // 禁用文本选择
      document.body.style.userSelect = 'none'
      window.addEventListener('mousemove', handleMouseMove, { passive: false })
      window.addEventListener('mouseup', handleMouseUp)

      return () => {
        // 恢复文本选择
        document.body.style.userSelect = ''
        window.removeEventListener('mousemove', handleMouseMove)
        window.removeEventListener('mouseup', handleMouseUp)
      }
    }
  }, [isDragging, isResizing, resizeDirection, node.id, node.locked, zoom, updateNode, onDragEnd, localPosition, localSize])

  // Handle double click to edit
  const handleDoubleClick = useCallback(
    (e: React.MouseEvent, field: 'title' | 'content') => {
      e.stopPropagation()
      if (!node.locked) {
        setEditingField(field)
      }
    },
    [node.locked]
  )

  // 中文输入法开始
  const handleCompositionStart = useCallback(() => {
    setIsComposing(true)
  }, [])

  // 中文输入法结束
  const handleCompositionEnd = useCallback(() => {
    setIsComposing(false)
  }, [])

  // 不做状态更新，避免光标跳动
  const handleInputChange = useCallback(() => {}, [])

  // Handle key down
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent, field: 'title' | 'content') => {
      if (isComposing) return

      // Prevent delete and backspace from bubbling up when editing
      if (e.key === 'Delete' || e.key === 'Backspace') {
        e.stopPropagation()
        return
      }

      if (e.key === 'Escape') {
        e.preventDefault()
        if (field === 'title') {
          saveTitle()
        } else {
          saveContent()
        }
        setEditingField(null)
      } else if (e.key === 'Enter' && !e.shiftKey) {
        if (field === 'title') {
          e.preventDefault()
          saveTitle()
          setEditingField('content')  // 按 Enter 从标题跳到内容
        } else {
          // 内容区域允许换行，不阻止
        }
      }
    },
    [isComposing, saveTitle, saveContent]
  )

  // Handle paste - 清理格式
  const handlePaste = useCallback((e: React.ClipboardEvent) => {
    e.preventDefault()
    const text = e.clipboardData.getData('text/plain')
    document.execCommand('insertText', false, text)
  }, [])

  // 失焦时保存
  const handleBlur = useCallback((field: 'title' | 'content') => {
    if (field === 'title' && isEditingTitle) {
      saveTitle()
    } else if (field === 'content' && isEditingContent) {
      saveContent()
    }
    setEditingField(null)
  }, [isEditingTitle, isEditingContent, saveTitle, saveContent])

  // Handle context menu
  const handleContextMenu = useCallback(
    (e: React.MouseEvent) => {
      if (editingField !== null) return
      e.preventDefault()
      e.stopPropagation()
      
      // Use mouse position with a small offset
      // This ensures the menu appears close to where the user clicked
      setContextMenuPosition({ 
        x: e.clientX + 5,  // 5px offset from mouse
        y: e.clientY + 5
      })
      
      setIsContextMenuOpen(true)
      if (!isSelected) {
        setSelectedIds([node.id])
      }
    },
    [editingField, isSelected, node.id, setSelectedIds]
  )

  // Toggle collapsed state
  const toggleCollapsed = useCallback(() => {
    const newCollapsed = !node.collapsed
    
    if (newCollapsed) {
      updateNode(node.id, { 
        collapsed: newCollapsed,
        expandedHeight: node.height,
        height: 36
      })
      setLocalSize({ width: node.width, height: 36 })
    } else {
      const expandedHeight = node.expandedHeight || node.height
      updateNode(node.id, { 
        collapsed: newCollapsed,
        height: expandedHeight
      })
      setLocalSize({ width: node.width, height: expandedHeight })
    }
  }, [node.id, node.collapsed, node.height, node.expandedHeight, node.width, updateNode])

  // Close context menu
  const closeContextMenu = useCallback(() => {
    setIsContextMenuOpen(false)
  }, [])

  // Handle image upload
  const handleImageUpload = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]
      if (!file) return

      if (!file.type.startsWith('image/')) {
        addToast({
          type: 'error',
          title: '无效文件',
          message: '请选择图片文件',
        })
        return
      }

      if (file.size > 10 * 1024 * 1024) {
        addToast({
          type: 'error',
          title: '文件过大',
          message: '请选择小于10MB的图片',
        })
        return
      }

      try {
        const uploadedFile = await uploadFile(file)
        const imageUrl = uploadedFile.path.startsWith('http')
          ? uploadedFile.path
          : `${import.meta.env.VITE_API_URL || 'http://localhost:3000'}${uploadedFile.path}`

        updateNode(node.id, { imageUrl })
        addToast({
          type: 'success',
          title: '图片已上传',
          message: '图片已添加到节点',
        })
      } catch (error) {
        addToast({
          type: 'error',
          title: '上传失败',
          message: error instanceof Error ? error.message : '上传图片失败',
        })
      }

      if (fileInputRef.current) {
        fileInputRef.current.value = ''
      }
    },
    [node.id, updateNode, addToast]
  )

  // Handle remove image
  const handleRemoveImage = useCallback(() => {
    updateNode(node.id, { imageUrl: undefined })
  }, [node.id, updateNode])

  return (
    <>
      <style>{`
        .node-dragging,
        .node-dragging * {
          cursor: move !important;
        }
      `}</style>
      <div
        ref={nodeRef}
        data-node-id={node.id}
        className={`node-item absolute border rounded-lg shadow-sm ${
          isDragging ? 'node-dragging' : node.locked ? 'cursor-not-allowed opacity-75' : editingField !== null ? 'cursor-text' : 'cursor-move'
        } ${isDragging ? 'shadow-lg scale-[1.02]' : ''} ${
          isSelected ? 'shadow-xl' : ''
        } ${isDragging || isResizing ? '' : 'transition-all duration-0'}`}
        style={{
          cursor: isDragging ? 'move' : undefined,
          // 使用本地状态，拖动时更流畅
          left: localPosition.x,
          top: localPosition.y,
          width: localSize.width,
          height: localSize.height,
          backgroundColor: node.color,
          borderColor: isSelected ? 'transparent' : node.borderColor,
          borderWidth: node.borderWidth,
          borderRadius: node.borderRadius,
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
          position: 'absolute',
          background: isSelected
            ? `linear-gradient(135deg, ${node.color} 0%, ${node.color}dd 100%)`
            : node.color,
        }}
        onMouseDown={handleMouseDown}
        onClick={(e) => {
          if (editingField !== null) return

          if (currentTool === 'connection') {
            const connectionStartEvent = new CustomEvent('connectionStart', {
              detail: {
                nodeId: node.id,
                mouseX: e.clientX,
                mouseY: e.clientY,
              },
              bubbles: true,
            })
            e.currentTarget.dispatchEvent(connectionStartEvent)
          } else {
            e.stopPropagation()
          }
        }}
        onContextMenu={handleContextMenu}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        {/* 选中状态的装饰性边框 */}
        {isSelected && (
          <div
            className="absolute inset-0 rounded-lg pointer-events-none"
            style={{
              border: '2px solid #3b82f6',
              boxShadow: '0 0 8px rgba(59, 130, 246, 0.4)',
            }}
          />
        )}
        {/* Node content */}
        {node.collapsed ? (
          // 折叠状态 - 只显示标题
          <div
            className="w-full h-full flex items-center justify-center px-3 text-sm truncate"
            style={{
              fontSize: node.fontSize + 2,
              textAlign: node.textAlign,
              color: '#374151',
              fontWeight: 'bold',
            }}
            title={node.title?.replace(/<[^>]*>/g, '') || node.content?.replace(/<[^>]*>/g, '')}
          >
            {node.title?.replace(/<[^>]*>/g, '') || node.content?.replace(/<[^>]*>/g, '') || '空白节点'}
          </div>
        ) : (
          // 展开状态 - 标题和内容分开
          <div className="w-full h-full flex flex-col">
            {/* 标题区域 */}
            <div
              className="flex-shrink-0 px-3 py-2 border-b border-gray-200 dark:border-gray-700"
              style={{ minHeight: '36px' }}
            >
              {isEditingTitle ? (
                <div
                  ref={titleRef}
                  contentEditable
                  suppressContentEditableWarning
                  className="outline-none font-bold"
                  style={{
                    fontSize: node.fontSize + 2,
                    textAlign: node.textAlign,
                    color: '#111827',
                    minHeight: '24px',
                  }}
                  onInput={handleInputChange}
                  onKeyDown={(e) => handleKeyDown(e, 'title')}
                  onCompositionStart={handleCompositionStart}
                  onCompositionEnd={handleCompositionEnd}
                  onPaste={handlePaste}
                  onBlur={() => handleBlur('title')}
                  onMouseDown={(e) => e.stopPropagation()}
                />
              ) : (
                <div
                  className="font-bold"
                  style={{
                    fontSize: node.fontSize + 2,
                    textAlign: node.textAlign,
                    color: '#111827',
                    minHeight: '24px',
                  }}
                  onDoubleClick={(e) => handleDoubleClick(e, 'title')}
                >
                  {node.title?.replace(/<[^>]*>/g, '') || '点击添加标题'}
                </div>
              )}
            </div>

            {/* 内容区域 */}
            <div className="flex-1 p-3 overflow-auto">
              {node.imageUrl && !editingField && (
                <img
                  src={node.imageUrl}
                  alt="节点图片"
                  className="w-full h-auto object-cover rounded mb-2"
                  style={{ maxHeight: node.height * 0.4 }}
                  onError={(e) => {
                    console.error('图片加载失败:', node.imageUrl)
                    e.currentTarget.style.display = 'none'
                  }}
                />
              )}
              {isEditingContent ? (
                <div
                  ref={contentRef}
                  contentEditable
                  suppressContentEditableWarning
                  className="outline-none"
                  style={{
                    fontSize: node.fontSize,
                    textAlign: node.textAlign,
                    color: '#374151',
                    minHeight: '60px',
                  }}
                  onInput={handleInputChange}
                  onKeyDown={(e) => handleKeyDown(e, 'content')}
                  onCompositionStart={handleCompositionStart}
                  onCompositionEnd={handleCompositionEnd}
                  onPaste={handlePaste}
                  onBlur={() => handleBlur('content')}
                  onMouseDown={(e) => e.stopPropagation()}
                />
              ) : (
                <div
                  style={{
                    fontSize: node.fontSize,
                    textAlign: node.textAlign,
                    color: '#374151',
                    minHeight: '40px',
                    wordBreak: 'break-word',
                  }}
                  onDoubleClick={(e) => handleDoubleClick(e, 'content')}
                  dangerouslySetInnerHTML={{ __html: node.content || '双击添加内容' }}
                />
              )}
            </div>
          </div>
        )}

        {/* Collapse/Expand button */}
        {editingField === null && (
          <button
            className="absolute top-1 right-1 w-5 h-5 flex items-center justify-center bg-gray-200 hover:bg-gray-300 rounded text-xs"
            onClick={(e) => {
              e.stopPropagation()
              toggleCollapsed()
            }}
            title={node.collapsed ? '展开' : '折叠'}
          >
            {node.collapsed ? '+' : '-'}
          </button>
        )}

        {/* Image upload button */}
        {(isSelected || isHovered) && editingField === null && !node.locked && !node.collapsed && (
          <button
            className="absolute bottom-1 right-1 w-6 h-6 flex items-center justify-center bg-blue-500 hover:bg-blue-600 rounded text-white text-xs"
            onClick={(e) => {
              e.stopPropagation()
              fileInputRef.current?.click()
            }}
            title="上传图片"
          >
            <svg
              className="w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
              />
            </svg>
          </button>
        )}

        {/* Remove image button */}
        {(isSelected || isHovered) && node.imageUrl && editingField === null && !node.locked && !node.collapsed && (
          <button
            className="absolute bottom-1 left-1 w-6 h-6 flex items-center justify-center bg-red-500 hover:bg-red-600 rounded text-white text-xs"
            onClick={(e) => {
              e.stopPropagation()
              handleRemoveImage()
            }}
            title="移除图片"
          >
            <svg
              className="w-4 h-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        )}

        {/* Hidden file input */}
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          className="hidden"
          onChange={handleImageUpload}
        />

        {/* Lock indicator */}
        {node.locked && (
          <div className="absolute top-1 left-1 w-4 h-4 flex items-center justify-center">
            <svg
              className="w-3 h-3 text-gray-500"
              fill="currentColor"
              viewBox="0 0 20 20"
            >
              <path
                fillRule="evenodd"
                d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z"
                clipRule="evenodd"
              />
            </svg>
          </div>
        )}

        {/* Resize handles */}
        {(isSelected || isHovered) && editingField === null && !node.locked && !node.collapsed && (
          <>
            <div
              data-resize="nw"
              className="absolute cursor-nw-resize"
              style={{
                top: -8,
                left: -8,
                width: RESIZE_HANDLE_SIZE,
                height: RESIZE_HANDLE_SIZE,
              }}
            >
              <div className="absolute inset-0 m-auto w-2 h-2 bg-blue-500 rounded-sm" />
            </div>
            <div
              data-resize="ne"
              className="absolute cursor-ne-resize"
              style={{
                top: -8,
                right: -8,
                width: RESIZE_HANDLE_SIZE,
                height: RESIZE_HANDLE_SIZE,
              }}
            >
              <div className="absolute inset-0 m-auto w-2 h-2 bg-blue-500 rounded-sm" />
            </div>
            <div
              data-resize="sw"
              className="absolute cursor-sw-resize"
              style={{
                bottom: -8,
                left: -8,
                width: RESIZE_HANDLE_SIZE,
                height: RESIZE_HANDLE_SIZE,
              }}
            >
              <div className="absolute inset-0 m-auto w-2 h-2 bg-blue-500 rounded-sm" />
            </div>
            <div
              data-resize="se"
              className="absolute cursor-se-resize"
              style={{
                bottom: -8,
                right: -8,
                width: RESIZE_HANDLE_SIZE,
                height: RESIZE_HANDLE_SIZE,
              }}
            >
              <div className="absolute inset-0 m-auto w-2 h-2 bg-blue-500 rounded-sm" />
            </div>
            <div
              data-resize="n"
              className="absolute cursor-n-resize"
              style={{ top: -4, left: '35%', right: '35%', height: 8 }}
            >
              <div className="absolute inset-0 m-auto h-1 w-full bg-blue-500 rounded-sm" />
            </div>
            <div
              data-resize="s"
              className="absolute cursor-s-resize"
              style={{ bottom: -4, left: '35%', right: '35%', height: 8 }}
            >
              <div className="absolute inset-0 m-auto h-1 w-full bg-blue-500 rounded-sm" />
            </div>
            <div
              data-resize="e"
              className="absolute cursor-e-resize"
              style={{ top: '35%', bottom: '35%', right: -4, width: 8 }}
            >
              <div className="absolute inset-0 m-auto w-1 h-full bg-blue-500 rounded-sm" />
            </div>
            <div
              data-resize="w"
              className="absolute cursor-w-resize"
              style={{ top: '35%', bottom: '35%', left: -4, width: 8 }}
            >
              <div className="absolute inset-0 m-auto w-1 h-full bg-blue-500 rounded-sm" />
            </div>
          </>
        )}
      </div>

      {/* Context menu */}
      {isContextMenuOpen && (
        <NodeContextMenu
          nodeId={node.id}
          position={contextMenuPosition}
          onClose={closeContextMenu}
        />
      )}
    </>
  )
}
