import { useState, useRef, useEffect } from 'react'
import { Plus, Folder, FolderOpen, FileText, Trash2, MoreVertical, Edit2, Check, X, GripVertical, Layers, FolderKanban, Calendar } from 'lucide-react'
import { useNavigate, useLocation } from 'react-router-dom'
import { useProjectsStore } from '@/store/useProjectsStore'
import { useUIStore } from '@/store/useUIStore'
import clsx from 'clsx'

interface SidebarProps {
  open: boolean
}

export function Sidebar({ open }: SidebarProps) {
  const navigate = useNavigate()
  const location = useLocation()
  const { projects, canvases, folders, currentProject, createCanvas, createFolder, updateCanvas, updateProject, deleteProject, setCurrentProject, loadProjects } = useProjectsStore()
  const { addToast } = useUIStore()

  // 判断当前是否在项目页面
  const isProjectsPage = location.pathname === '/projects'
  const [draggedCanvas, setDraggedCanvas] = useState<any>(null)
  const [dragOverFolder, setDragOverFolder] = useState<number | null>(null)
  const [isDragOverRoot, setIsDragOverRoot] = useState(false)
  // 管理文件夹展开状态
  const [expandedFolderIds, setExpandedFolderIds] = useState<Set<number>>(new Set())

  const handleCreateCanvas = async () => {
    if (!currentProject) {
      addToast({ type: 'warning', title: '未选择项目', message: '请先选择一个项目' })
      return
    }

    try {
      await createCanvas(currentProject.id, {
        name: `未命名画布 ${canvases.length + 1}`,
        projectId: currentProject.id,
      })
    } catch (error) {
      addToast({ type: 'error', title: '创建画布失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleCreateFolder = async () => {
    if (!currentProject) {
      addToast({ type: 'warning', title: '未选择项目', message: '请先选择一个项目' })
      return
    }

    try {
      await createFolder(currentProject.id, {
        name: '新建文件夹',
        projectId: currentProject.id,
        parentId: null,
        sortOrder: 0,
      })
    } catch (error) {
      addToast({ type: 'error', title: '创建文件夹失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleDragStart = (canvas: any) => {
    setDraggedCanvas(canvas)
  }

  const handleDragEnd = () => {
    setDraggedCanvas(null)
    setDragOverFolder(null)
    setIsDragOverRoot(false)
  }

  // 切换文件夹展开状态
  const handleToggleFolder = (folderId: number) => {
    setExpandedFolderIds(prev => {
      const newSet = new Set(prev)
      if (newSet.has(folderId)) {
        newSet.delete(folderId)
      } else {
        newSet.add(folderId)
      }
      return newSet
    })
  }

  const handleDragOverFolder = (e: React.DragEvent, folderId: number) => {
    e.preventDefault()
    e.stopPropagation()
    setDragOverFolder(folderId)
  }

  const handleDragOverRoot = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragOverRoot(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    const currentTarget = e.currentTarget
    const relatedTarget = e.relatedTarget as HTMLElement

    // 只有当鼠标真正离开元素时才清除状态，而不是移动到子元素
    // 如果 relatedTarget 为 null，说明拖拽到了元素外部
    if (!relatedTarget || !currentTarget.contains(relatedTarget)) {
      setDragOverFolder(null)
      setIsDragOverRoot(false)
    }
  }

  const handleDropOnFolder = async (e: React.DragEvent, folderId: number) => {
    e.preventDefault()
    e.stopPropagation()

    if (!draggedCanvas) return

    try {
      await updateCanvas(draggedCanvas.id, { folderId: folderId })
      if (draggedCanvas.folderId !== folderId) {
        addToast({ type: 'success', title: '已移动', message: '画布已移动到文件夹' })
      }
      setExpandedFolderIds(prev => new Set([...prev, folderId]))
    } catch (error) {
      addToast({ type: 'error', title: '移动失败', message: error instanceof Error ? error.message : '未知错误' })
    }

    handleDragEnd()
  }

  const handleDropOnRoot = async (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()

    if (!draggedCanvas) return

    try {
      await updateCanvas(draggedCanvas.id, { folderId: null })
      addToast({ type: 'success', title: '已移动', message: '画布已移出文件夹' })
    } catch (error) {
      addToast({ type: 'error', title: '移动失败', message: error instanceof Error ? error.message : '未知错误' })
    }

    handleDragEnd()
  }

  const rootCanvases = canvases.filter((c) => !c.folderId)
  const [editingProjectId, setEditingProjectId] = useState<number | null>(null)
  const [editProjectName, setEditProjectName] = useState('')
  const [editProjectDesc, setEditProjectDesc] = useState('')
  const [showProjectMenu, setShowProjectMenu] = useState<number | null>(null)
  const projectMenuRef = useRef<HTMLDivElement>(null)

  // 加载项目列表
  useEffect(() => {
    loadProjects()
  }, [loadProjects])

  // 全局拖拽结束监听 - 确保在任何情况下都重置拖拽状态
  useEffect(() => {
    const handleDragEnd = () => {
      setDraggedCanvas(null)
      setDragOverFolder(null)
      setIsDragOverRoot(false)
    }

    document.addEventListener('dragend', handleDragEnd)

    return () => {
      document.removeEventListener('dragend', handleDragEnd)
    }
  }, [])

  // 点击外部关闭项目菜单
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (projectMenuRef.current && !projectMenuRef.current.contains(event.target as Node)) {
        setShowProjectMenu(null)
      }
    }

    if (showProjectMenu !== null) {
      document.addEventListener('mousedown', handleClickOutside)
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [showProjectMenu])

  const handleSelectProject = async (project: any) => {
    await setCurrentProject(project)
    navigate(`/canvas/new`)
  }

  const handleBackToProjects = () => {
    setCurrentProject(null)
    navigate('/projects')
  }

  const handleStartEditProject = (project: any) => {
    setEditProjectName(project.name)
    setEditProjectDesc(project.description || '')
    setEditingProjectId(project.id)
    setShowProjectMenu(null)
  }

  const handleSaveProject = async () => {
    if (!editProjectName.trim()) {
      addToast({ type: 'warning', title: '名称不能为空', message: '请输入项目名称' })
      return
    }

    if (!editingProjectId) return

    try {
      await updateProject(editingProjectId, {
        name: editProjectName.trim(),
        description: editProjectDesc.trim() || null,
      })
      addToast({ type: 'success', title: '已更新', message: '项目信息已更新' })
      setEditingProjectId(null)
    } catch (error) {
      addToast({ type: 'error', title: '更新失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleCancelEditProject = () => {
    setEditingProjectId(null)
    setEditProjectName('')
    setEditProjectDesc('')
  }

  const handleDeleteProject = async (project: any) => {
    if (!confirm(`确定要删除项目"${project.name}"吗？项目内的所有画布和文件夹也将被删除。此操作不可恢复。`)) {
      return
    }

    try {
      await deleteProject(project.id)
      addToast({ type: 'success', title: '已删除', message: '项目已被删除' })
      setShowProjectMenu(null)
    } catch (error) {
      addToast({ type: 'error', title: '删除失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  return (
    <aside
      className={clsx(
        'bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700 flex flex-col transition-all duration-200',
        open ? 'w-64' : 'w-0'
      )}
    >
      {isProjectsPage || !currentProject ? (
        // 项目选择视图
        <>
          <div className="h-14 border-b border-gray-200 dark:border-gray-700 flex items-center px-4 flex-shrink-0">
            <h2 className="font-semibold text-gray-800 dark:text-white">项目</h2>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar p-3">
            {projects.length === 0 ? (
              <div className="text-center py-8">
                <FolderKanban className="w-12 h-12 text-gray-400 mx-auto mb-3" />
                <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">还没有项目</p>
                <button
                  onClick={() => navigate('/projects')}
                  className="text-sm text-blue-600 dark:text-blue-400 hover:underline"
                >
                  创建项目
                </button>
              </div>
            ) : (
              <div className="space-y-2">
                {projects.map((project) => (
                  <div
                    key={project.id}
                    className={clsx(
                      'p-3 rounded-lg transition-colors group',
                      editingProjectId === project.id
                        ? 'bg-blue-50 dark:bg-blue-900/30'
                        : 'bg-gray-50 dark:bg-gray-700 hover:bg-blue-50 dark:hover:bg-blue-900/20'
                    )}
                  >
                    {editingProjectId === project.id ? (
                      // 编辑模式
                      <div className="space-y-2">
                        <input
                          type="text"
                          value={editProjectName}
                          onChange={(e) => setEditProjectName(e.target.value)}
                          onKeyDown={(e) => e.key === 'Enter' && handleSaveProject()}
                          placeholder="项目名称"
                          className="w-full px-2 py-1 text-sm bg-white dark:bg-gray-800 border border-blue-500 rounded focus:outline-none text-gray-900 dark:text-white"
                          autoFocus
                        />
                        <textarea
                          value={editProjectDesc}
                          onChange={(e) => setEditProjectDesc(e.target.value)}
                          placeholder="描述（可选）"
                          rows={2}
                          className="w-full px-2 py-1 text-sm bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded focus:outline-none text-gray-900 dark:text-white resize-none"
                        />
                        <div className="flex items-center gap-2">
                          <button
                            onClick={handleSaveProject}
                            className="flex items-center gap-1 px-2 py-1 text-xs bg-green-600 hover:bg-green-700 text-white rounded transition-colors"
                          >
                            <Check className="w-3 h-3" />
                            保存
                          </button>
                          <button
                            onClick={handleCancelEditProject}
                            className="flex items-center gap-1 px-2 py-1 text-xs bg-gray-400 hover:bg-gray-500 text-white rounded transition-colors"
                          >
                            <X className="w-3 h-3" />
                            取消
                          </button>
                        </div>
                      </div>
                    ) : (
                      // 查看模式
                      <div
                        onClick={() => handleSelectProject(project)}
                        className="cursor-pointer"
                      >
                        <div className="flex items-start justify-between">
                          <div className="flex-1 min-w-0 pr-2">
                            <h3 className="font-medium text-gray-900 dark:text-white text-sm truncate">
                              {project.name}
                            </h3>
                            {project.description && (
                              <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
                                {project.description}
                              </p>
                            )}
                            <div className="flex items-center gap-2 mt-2 text-xs text-gray-500 dark:text-gray-400">
                              <Calendar className="w-3 h-3" />
                              <span>{new Date(project.updatedAt).toLocaleDateString()}</span>
                            </div>
                          </div>
                          <div className="relative" ref={projectMenuRef}>
                            <button
                              onClick={(e) => {
                                e.stopPropagation()
                                setShowProjectMenu(showProjectMenu === project.id ? null : project.id)
                              }}
                              className="opacity-0 group-hover:opacity-100 p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-600"
                            >
                              <MoreVertical className="w-4 h-4 text-gray-600 dark:text-gray-400" />
                            </button>

                            {/* 下拉菜单 */}
                            {showProjectMenu === project.id && (
                              <div className="absolute right-0 top-full mt-1 w-32 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 py-1 z-50">
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation()
                                    handleStartEditProject(project)
                                  }}
                                  className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                                >
                                  <Edit2 className="w-3 h-3" />
                                  重命名
                                </button>
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation()
                                    handleDeleteProject(project)
                                  }}
                                  className="w-full flex items-center gap-2 px-3 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/30"
                                >
                                  <Trash2 className="w-3 h-3" />
                                  删除
                                </button>
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      ) : (
        // 项目和画布管理视图
        <>
          {/* 项目信息区域 */}
          <div className="border-b border-gray-200 dark:border-gray-700">
            <div className="p-4">
              <div className="flex items-center justify-between mb-3">
                <button
                  onClick={handleBackToProjects}
                  className="flex items-center gap-1 text-sm text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"
                >
                  <Layers className="w-4 h-4" />
                  返回项目列表
                </button>
              </div>
              <div className="bg-gradient-to-br from-blue-50 to-purple-50 dark:from-blue-900/20 dark:to-purple-900/20 rounded-lg p-3">
                <h3 className="font-semibold text-gray-900 dark:text-white truncate text-sm">
                  {currentProject.name}
                </h3>
                {currentProject.description && (
                  <p className="text-xs text-gray-600 dark:text-gray-400 mt-1 line-clamp-2">
                    {currentProject.description}
                  </p>
                )}
              </div>
            </div>
          </div>

          {/* 画布管理区域 */}
          <div className="flex-1 flex flex-col min-h-0">
            <div className="h-12 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between px-4 flex-shrink-0">
              <h2 className="font-semibold text-gray-800 dark:text-white">画布管理</h2>
              <div className="flex items-center gap-1">
                <button
                  onClick={handleCreateFolder}
                  className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
                  title="新建文件夹"
                >
                  <Folder className="w-4 h-4" />
                </button>
                <button
                  onClick={handleCreateCanvas}
                  className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
                  title="新建画布"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
              {folders.map((folder) => (
                <FolderItem
                  key={folder.id}
                  folder={folder}
                  canvases={canvases}
                  draggedCanvas={draggedCanvas}
                  dragOverFolder={dragOverFolder}
                  isExpanded={expandedFolderIds.has(folder.id)}
                  onToggle={handleToggleFolder}
                  onDragStart={handleDragStart}
                  onDragOver={handleDragOverFolder}
                  onDragLeave={handleDragLeave}
                  onDrop={handleDropOnFolder}
                />
              ))}

              <div
                onDragOver={handleDragOverRoot}
                onDragLeave={(e) => handleDragLeave(e)}
                onDrop={handleDropOnRoot}
                className={clsx(
                  'rounded transition-colors',
                  isDragOverRoot && 'bg-blue-50 dark:bg-blue-900/20'
                )}
              >
                {rootCanvases.map((canvas) => (
                  <CanvasItem
                    key={canvas.id}
                    canvas={canvas}
                    isDragging={draggedCanvas?.id === canvas.id}
                    onDragStart={handleDragStart}
                    onDragEnd={handleDragEnd}
                  />
                ))}
              </div>
            </div>
          </div>
        </>
      )}
    </aside>
  )
}

function FolderItem({
  folder,
  canvases,
  draggedCanvas,
  dragOverFolder,
  isExpanded,
  onToggle,
  onDragStart,
  onDragOver,
  onDragLeave,
  onDrop,
}: {
  folder: any
  canvases: any[]
  draggedCanvas: any
  dragOverFolder: number | null
  isExpanded: boolean
  onToggle: (folderId: number) => void
  onDragStart: (canvas: any) => void
  onDragOver: (e: React.DragEvent, folderId: number) => void
  onDragLeave: (e: React.DragEvent) => void
  onDrop: (e: React.DragEvent, folderId: number) => void
}) {
  const { updateFolder, deleteFolder } = useProjectsStore()
  const { addToast } = useUIStore()
  const [isEditing, setIsEditing] = useState(false)
  const [editName, setEditName] = useState(folder.name)
  const [showMenu, setShowMenu] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)
  const menuRef = useRef<HTMLDivElement>(null)

  // 点击外部关闭菜单
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false)
      }
    }

    if (showMenu) {
      document.addEventListener('mousedown', handleClickOutside)
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [showMenu])

  // 进入编辑模式时聚焦输入框
  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus()
      inputRef.current.select()
    }
  }, [isEditing])

  const handleToggle = () => {
    if (!isEditing) {
      onToggle(folder.id)
    }
  }

  const handleStartEdit = () => {
    setEditName(folder.name)
    setIsEditing(true)
    setShowMenu(false)
  }

  const handleSaveEdit = async () => {
    if (!editName.trim()) {
      addToast({ type: 'warning', title: '名称不能为空', message: '请输入文件夹名称' })
      return
    }

    if (editName === folder.name) {
      setIsEditing(false)
      return
    }

    try {
      await updateFolder(folder.id, { name: editName.trim() })
      addToast({ type: 'success', title: '已重命名', message: '文件夹名称已更新' })
    } catch (error) {
      addToast({ type: 'error', title: '重命名失败', message: error instanceof Error ? error.message : '未知错误' })
    }
    setIsEditing(false)
  }

  const handleCancelEdit = () => {
    setEditName(folder.name)
    setIsEditing(false)
  }

  const handleDelete = async () => {
    const folderCanvases = canvases.filter((c) => c.folderId === folder.id)
    const confirmMessage = folderCanvases.length > 0
      ? `确定要删除文件夹"${folder.name}"吗？文件夹内的 ${folderCanvases.length} 个画布也将被删除。此操作不可恢复。`
      : `确定要删除文件夹"${folder.name}"吗？此操作不可恢复。`

    if (!confirm(confirmMessage)) {
      return
    }

    try {
      await deleteFolder(folder.id)
      addToast({ type: 'success', title: '已删除', message: '文件夹已被删除' })
      setShowMenu(false)
    } catch (error) {
      addToast({ type: 'error', title: '删除失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSaveEdit()
    } else if (e.key === 'Escape') {
      handleCancelEdit()
    }
  }

  const folderCanvases = canvases.filter((c) => c.folderId === folder.id)
  const isDropTarget = dragOverFolder === folder.id

  return (
    <div className="mb-2">
      {isEditing ? (
        // 编辑模式
        <div className="flex items-center gap-1 px-2 py-1.5 rounded bg-blue-50 dark:bg-blue-900/30">
          <Folder className="w-4 h-4 text-gray-400 flex-shrink-0" />
          <input
            ref={inputRef}
            type="text"
            value={editName}
            onChange={(e) => setEditName(e.target.value)}
            onKeyDown={handleKeyDown}
            className="flex-1 text-sm bg-transparent border-b border-blue-500 outline-none text-gray-700 dark:text-gray-300 px-1"
          />
          <button
            onClick={handleSaveEdit}
            className="p-1 rounded hover:bg-green-100 dark:hover:bg-green-900/30 text-green-600 dark:text-green-400"
            title="保存"
          >
            <Check className="w-3 h-3" />
          </button>
          <button
            onClick={handleCancelEdit}
            className="p-1 rounded hover:bg-red-100 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400"
            title="取消"
          >
            <X className="w-3 h-3" />
          </button>
        </div>
      ) : (
        // 查看模式
        <div className="relative group">
          <div
            onDragOver={(e) => {
              e.preventDefault()
              e.stopPropagation()
              onDragOver(e, folder.id)
            }}
            onDragLeave={(e) => {
              e.stopPropagation()
              onDragLeave(e)
            }}
            onDrop={(e) => {
              e.preventDefault()
              e.stopPropagation()
              onDrop(e, folder.id)
            }}
            className={clsx(
              'w-full rounded transition-colors',
              isDropTarget && 'bg-blue-50 dark:bg-blue-900/20'
            )}
          >
            <div
              onClick={handleToggle}
              className="w-full flex items-center gap-2 px-2 py-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300 cursor-pointer"
            >
              <div onClick={(e) => e.stopPropagation()}>
                {isExpanded ? (
                  <FolderOpen className="w-4 h-4" />
                ) : (
                  <Folder className="w-4 h-4" />
                )}
              </div>
              <span className="text-sm flex-1 truncate">{folder.name}</span>
              <span className="text-xs text-gray-500 dark:text-gray-400 bg-gray-100 dark:bg-gray-700 px-1.5 py-0.5 rounded">
                {folderCanvases.length}
              </span>
              <div className="relative" onClick={(e) => e.stopPropagation()}>
                <button
                  onClick={() => setShowMenu(!showMenu)}
                  className="opacity-0 group-hover:opacity-100 p-1 rounded hover:bg-gray-200 dark:hover:bg-gray-600"
                >
                  <MoreVertical className="w-3 h-3" />
                </button>

                {/* 下拉菜单 */}
                {showMenu && (
                  <div
                    ref={menuRef}
                    className="absolute right-0 top-full mt-1 w-32 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 py-1 z-50"
                  >
                    <button
                      onClick={handleStartEdit}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                    >
                      <Edit2 className="w-3 h-3" />
                      重命名
                    </button>
                    <button
                      onClick={handleDelete}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/30"
                    >
                      <Trash2 className="w-3 h-3" />
                      删除
                    </button>
                  </div>
                )}
              </div>
            </div>

            {isExpanded && (
              <div 
                className="ml-4 mt-1"
                onDragOver={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                  onDragOver(e, folder.id)
                }}
                onDragLeave={(e) => {
                  e.stopPropagation()
                  onDragLeave(e)
                }}
                onDrop={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                  onDrop(e, folder.id)
                }}
              >
                {folderCanvases.map((canvas) => (
                  <CanvasItem
                    key={canvas.id}
                    canvas={canvas}
                    isDragging={draggedCanvas?.id === canvas.id}
                    onDragStart={onDragStart}
                    onDragEnd={() => {}}
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

function CanvasItem({
  canvas,
  isDragging,
  onDragStart,
  onDragEnd,
}: {
  canvas: any
  isDragging?: boolean
  onDragStart: (canvas: any) => void
  onDragEnd: () => void
}) {
  const navigate = useNavigate()
  const { updateCanvas, deleteCanvas, folders } = useProjectsStore()
  const { addToast } = useUIStore()
  const [isEditing, setIsEditing] = useState(false)
  const [editName, setEditName] = useState(canvas.name)
  const [showContextMenu, setShowContextMenu] = useState(false)
  const [showMoveMenu, setShowMoveMenu] = useState(false)
  const [contextMenuPosition, setContextMenuPosition] = useState({ x: 0, y: 0 })
  const inputRef = useRef<HTMLInputElement>(null)
  const contextMenuRef = useRef<HTMLDivElement>(null)

  // 点击外部关闭菜单
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (contextMenuRef.current && !contextMenuRef.current.contains(event.target as Node)) {
        setShowContextMenu(false)
        setShowMoveMenu(false)
      }
    }

    if (showContextMenu) {
      document.addEventListener('mousedown', handleClickOutside)
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [showContextMenu])

  // 进入编辑模式时聚焦输入框
  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus()
      inputRef.current.select()
    }
  }, [isEditing])

  const handleStartEdit = () => {
    setEditName(canvas.name)
    setIsEditing(true)
    setShowContextMenu(false)
  }

  const handleSaveEdit = async () => {
    if (!editName.trim()) {
      addToast({ type: 'warning', title: '名称不能为空', message: '请输入画布名称' })
      return
    }

    if (editName === canvas.name) {
      setIsEditing(false)
      return
    }

    try {
      await updateCanvas(canvas.id, { name: editName.trim() })
      addToast({ type: 'success', title: '已重命名', message: '画布名称已更新' })
    } catch (error) {
      addToast({ type: 'error', title: '重命名失败', message: error instanceof Error ? error.message : '未知错误' })
    }
    setIsEditing(false)
  }

  const handleCancelEdit = () => {
    setEditName(canvas.name)
    setIsEditing(false)
  }

  const handleDelete = async () => {
    if (!confirm(`确定要删除画布"${canvas.name}"吗？此操作不可恢复。`)) {
      return
    }

    try {
      await deleteCanvas(canvas.id)
      addToast({ type: 'success', title: '已删除', message: '画布已被删除' })
      setShowContextMenu(false)
    } catch (error) {
      addToast({ type: 'error', title: '删除失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setContextMenuPosition({ x: e.clientX, y: e.clientY })
    setShowContextMenu(true)
    setShowMoveMenu(false)
  }

  const handleMoveToFolder = async (folderId: number | null) => {
    try {
      await updateCanvas(canvas.id, { folderId })
      const folderName = folderId ? folders.find(f => f.id === folderId)?.name : '根目录'
      addToast({ type: 'success', title: '已移动', message: `画布已移动到"${folderName}"` })
      setShowContextMenu(false)
      setShowMoveMenu(false)
    } catch (error) {
      addToast({ type: 'error', title: '移动失败', message: error instanceof Error ? error.message : '未知错误' })
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSaveEdit()
    } else if (e.key === 'Escape') {
      handleCancelEdit()
    }
  }

  return (
    <div className="relative group mb-2">
      {isEditing ? (
        // 编辑模式
        <div className="p-2 rounded bg-blue-50 dark:bg-blue-900/30">
          <input
            ref={inputRef}
            type="text"
            value={editName}
            onChange={(e) => setEditName(e.target.value)}
            onKeyDown={handleKeyDown}
            className="w-full text-sm bg-white dark:bg-gray-800 border border-blue-500 rounded px-2 py-1.5 outline-none text-gray-700 dark:text-gray-300 mb-2"
            placeholder="画布名称"
          />
          <div className="flex items-center gap-2">
            <button
              onClick={handleSaveEdit}
              className="flex-1 flex items-center justify-center gap-1 px-2 py-1 text-sm bg-green-600 hover:bg-green-700 text-white rounded transition-colors"
            >
              <Check className="w-3 h-3" />
              保存
            </button>
            <button
              onClick={handleCancelEdit}
              className="flex-1 flex items-center justify-center gap-1 px-2 py-1 text-sm bg-gray-400 hover:bg-gray-500 text-white rounded transition-colors"
            >
              <X className="w-3 h-3" />
              取消
            </button>
          </div>
        </div>
      ) : (
        // 查看模式 - 缩略图卡片
        <div
          draggable
          onDragStart={() => onDragStart(canvas)}
          onDragEnd={onDragEnd}
          onContextMenu={handleContextMenu}
          className={clsx(
            'relative rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 hover:border-blue-400 dark:hover:border-blue-500 hover:shadow-md transition-all cursor-pointer group',
            isDragging && 'opacity-50'
          )}
        >
          {/* 缩略图区域 */}
          <div
            onClick={() => navigate(`/canvas/${canvas.id}`)}
            className="aspect-video bg-gradient-to-br from-gray-100 to-gray-200 dark:from-gray-700 dark:to-gray-800 rounded-t-lg relative overflow-hidden"
          >
            {canvas.thumbnail ? (
              <img
                src={canvas.thumbnail}
                alt={canvas.name}
                className="w-full h-full object-cover"
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center">
                <FileText className="w-8 h-8 text-gray-400 dark:text-gray-600" />
              </div>
            )}

            {/* 悬停时的遮罩 */}
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center">
              <span className="text-white opacity-0 group-hover:opacity-100 transition-opacity text-sm font-medium">
                打开画布
              </span>
            </div>
          </div>

          {/* 画布信息 */}
          <div className="p-2">
            <h4
              onClick={() => navigate(`/canvas/${canvas.id}`)}
              className="text-sm font-medium text-gray-900 dark:text-white truncate pr-6"
            >
              {canvas.name}
            </h4>
            {canvas.updatedAt && (
              <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                {new Date(canvas.updatedAt).toLocaleDateString()}
              </p>
            )}
          </div>

          {/* 右键菜单 */}
          {showContextMenu && (
            <div
              ref={contextMenuRef}
              className="fixed bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 py-1 z-50 min-w-[160px]"
              style={{
                left: contextMenuPosition.x,
                top: contextMenuPosition.y
              }}
            >
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  setShowMoveMenu(!showMoveMenu)
                }}
                className="w-full flex items-center justify-between gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
              >
                <div className="flex items-center gap-2">
                  <Folder className="w-3 h-3" />
                  移动到
                </div>
                <span className="text-gray-400">›</span>
              </button>

              {showMoveMenu && (
                <div className="border-t border-gray-200 dark:border-gray-700">
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      handleMoveToFolder(null)
                    }}
                    className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                  >
                    <span className="w-3 h-3" />
                    根目录
                  </button>
                  {folders.map((folder) => (
                    <button
                      key={folder.id}
                      onClick={(e) => {
                        e.stopPropagation()
                        handleMoveToFolder(folder.id)
                      }}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
                    >
                      <Folder className="w-3 h-3" />
                      {folder.name}
                    </button>
                  ))}
                </div>
              )}

              <button
                onClick={(e) => {
                  e.stopPropagation()
                  handleStartEdit()
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700"
              >
                <Edit2 className="w-3 h-3" />
                重命名
              </button>
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  handleDelete()
                }}
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/30"
              >
                <Trash2 className="w-3 h-3" />
                删除
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}
