import { MousePointer2, Square, Layers, Link, Eraser, Grid3x3, Save, Download, Undo, Redo, Trash2, ArrowRight, ArrowLeftRight, Minus, Group } from 'lucide-react'
import { useCanvasStore } from '@/store/useCanvasStore'
import { useUIStore } from '@/store/useUIStore'
import { SHORTCUTS } from '@/constants'
import type { Tool } from '@/types'
import { useState, useRef, useEffect } from 'react'
import { generateId } from '@/utils/canvas'
import { debugLogger } from '@/utils/debugLogger'

const tools: { id: Tool; icon: typeof MousePointer2; label: string; shortcut: string }[] = [
  { id: 'select', icon: MousePointer2, label: '选择/拖拽', shortcut: 'V' },
  { id: 'node', icon: Square, label: '节点', shortcut: 'N' },
  { id: 'group', icon: Layers, label: '分组', shortcut: '' },
  { id: 'connection', icon: Link, label: '连线', shortcut: 'L' },
  { id: 'eraser', icon: Eraser, label: '橡皮擦', shortcut: 'E' },
]

const connectionDirections = [
  { id: 'directed' as const, icon: ArrowRight, label: '单向连线' },
  { id: 'bidirectional' as const, icon: ArrowLeftRight, label: '双向连线' },
  { id: 'undirected' as const, icon: Minus, label: '无向连线' },
]

export function CanvasToolbar() {
  const { currentTool, gridVisible, dragMode, setCurrentTool, toggleGrid, toggleDragMode, connectionDirection, setConnectionDirection } = useUIStore()
  const { zoom, setZoom, setPan, selectedIds, removeNode, removeConnection, nodes, connections, undo, redo, history, groups, addGroup } = useCanvasStore()

  const [showConnectionMenu, setShowConnectionMenu] = useState(false)
  const connectionMenuRef = useRef<HTMLDivElement>(null)

  const canUndo = history.currentIndex >= 0
  const canRedo = history.currentIndex < history.commands.length - 1

  useEffect(() => {
    debugLogger.debug('Current tool changed:', currentTool)
  }, [currentTool])

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (connectionMenuRef.current && !connectionMenuRef.current.contains(event.target as Node)) {
        setShowConnectionMenu(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [])

  const handleDelete = () => {
    selectedIds.forEach((id) => {
      if (nodes.has(id)) {
        removeNode(id)
      } else if (connections.has(id)) {
        removeConnection(id)
      }
    })
  }

  const hasSelectedNodes = selectedIds.some(id => nodes.has(id))

  const handleCreateGroup = () => {
    if (hasSelectedNodes) {
      const selectedNodes = selectedIds.map(id => nodes.get(id)).filter(Boolean)
      if (selectedNodes.length > 0) {
        let minX = Infinity
        let minY = Infinity
        let maxX = -Infinity
        let maxY = -Infinity

        selectedNodes.forEach(node => {
          minX = Math.min(minX, node.x)
          minY = Math.min(minY, node.y)
          maxX = Math.max(maxX, node.x + node.width)
          maxY = Math.max(maxY, node.y + node.height)
        })

        const newGroup = {
          id: generateId('group'),
          name: `组 ${groups.size + 1}`,
          x: minX - 10,
          y: minY - 10,
          width: maxX - minX + 20,
          height: maxY - minY + 20,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          borderWidth: 2,
          borderRadius: 8,
          nodeIds: selectedIds,
          collapsed: false,
        }
        addGroup(newGroup)
      }
    }
  }

  return (
    <div className="h-12 border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 flex items-center justify-between px-4">
      {/* Left - Tools */}
      <div className="flex items-center gap-1">
        {tools.map((tool) => {
          const Icon = tool.icon
          const isActive = currentTool === tool.id

          if (tool.id === 'connection') {
            return (
              <div key={tool.id} className="relative" ref={connectionMenuRef}>
                <div
                  onClick={() => {
                    if (showConnectionMenu) {
                      setShowConnectionMenu(false)
                    } else {
                      setShowConnectionMenu(true)
                    }
                  }}
                  className={`
                    p-2 rounded-lg transition-colors relative cursor-pointer
                    ${isActive
                      ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                      : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
                    }
                  `}
                  title={`${tool.label} (${tool.shortcut})`}
                >
                  <Icon className="w-5 h-5" />
                  {showConnectionMenu && (
                    <div className="absolute left-0 top-full mt-1 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-lg py-1 min-w-[140px] z-50">
                      {connectionDirections.map((dir) => {
                        const DirIcon = dir.icon
                        const isDirActive = connectionDirection === dir.id
                        return (
                          <button
                            key={dir.id}
                            onClick={() => {
                              setConnectionDirection(dir.id)
                              setCurrentTool('connection')
                              setShowConnectionMenu(false)
                            }}
                            className={`
                              w-full px-3 py-2 text-left text-sm flex items-center gap-2 transition-colors
                              ${isDirActive
                                ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                                : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
                              }
                            `}
                          >
                            <DirIcon className="w-4 h-4" />
                            {dir.label}
                          </button>
                        )
                      })}
                    </div>
                  )}
                </div>
              </div>
            )
          }

          return (
            <button
              key={tool.id}
              onClick={() => setCurrentTool(tool.id)}
              className={`
                p-2 rounded-lg transition-colors cursor-pointer
                ${isActive
                  ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                  : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
                }
              `}
              title={`${tool.label} (${tool.shortcut})`}
            >
              <Icon className="w-5 h-5" />
            </button>
          )
        })}
      </div>

      {/* Center - View options */}
      <div className="flex items-center gap-2">
        <button
          onClick={toggleDragMode}
          className={`
            px-3 py-1.5 rounded-lg text-sm font-medium transition-colors
            ${dragMode === 'grid'
              ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
              : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
            }
          `}
          title="切换拖动模式 (Shift)"
        >
          {dragMode === 'grid' ? '网格吸附' : '自由移动'}
        </button>

        <button
          onClick={toggleGrid}
          className={`
            p-2 rounded-lg transition-colors
            ${gridVisible
              ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
              : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
            }
          `}
          title="切换网格 (G)"
        >
          <Grid3x3 className="w-5 h-5" />
        </button>

        <div className="h-6 w-px bg-gray-300 dark:bg-gray-600" />

        <span className="text-sm text-gray-600 dark:text-gray-400 min-w-[60px] text-center">
          {Math.round(zoom * 100)}%
        </span>
      </div>

      {/* Right - Actions */}
      <div className="flex items-center gap-1">
        <button
          onClick={handleCreateGroup}
          disabled={!hasSelectedNodes}
          className={`
            p-2 rounded-lg transition-colors
            ${hasSelectedNodes
              ? 'hover:bg-blue-100 dark:hover:bg-blue-900/30 text-blue-600 dark:text-blue-400'
              : 'text-gray-300 dark:text-gray-600 cursor-not-allowed'
            }
          `}
          title="创建组 (Ctrl+G)"
        >
          <Group className="w-5 h-5" />
        </button>

        <button
          onClick={handleDelete}
          disabled={selectedIds.length === 0}
          className={`
            p-2 rounded-lg transition-colors
            ${selectedIds.length > 0
              ? 'hover:bg-red-100 dark:hover:bg-red-900/30 text-red-600 dark:text-red-400'
              : 'text-gray-300 dark:text-gray-600 cursor-not-allowed'
            }
          `}
          title="删除选中项 (Delete)"
        >
          <Trash2 className="w-5 h-5" />
        </button>

        <div className="h-6 w-px bg-gray-300 dark:bg-gray-600" />

        <button
          onClick={undo}
          disabled={!canUndo}
          className={`
            p-2 rounded-lg transition-colors
            ${canUndo
              ? 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
              : 'text-gray-300 dark:text-gray-600 cursor-not-allowed'
            }
          `}
          title="撤销 (Ctrl+Z)"
        >
          <Undo className="w-5 h-5" />
        </button>

        <button
          onClick={redo}
          disabled={!canRedo}
          className={`
            p-2 rounded-lg transition-colors
            ${canRedo
              ? 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400'
              : 'text-gray-300 dark:text-gray-600 cursor-not-allowed'
            }
          `}
          title="重做 (Ctrl+Y)"
        >
          <Redo className="w-5 h-5" />
        </button>

        <div className="h-6 w-px bg-gray-300 dark:bg-gray-600" />

        <button
          className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
          title="保存 (Ctrl+S)"
        >
          <Save className="w-5 h-5" />
        </button>

        <button
          className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
          title="导出 (Ctrl+E)"
        >
          <Download className="w-5 h-5" />
        </button>


      </div>
    </div>
  )
}
